	/**
	 * Loops over the collection to check to see if the given object is in that collection. This method
	 * <i>only</i> uses the .equals() method for comparison. This should be used in the patient/person
	 * objects on their collections. Their collections are SortedSets which use the compareTo method for
	 * equality as well. The compareTo method is currently optimized for sorting, not for equality. A
	 * null <code>obj</code> will return false
	 * <p>
	 * <strong>Should</strong> use equals method for comparison instead of compareTo given List
	 * collection<br/>
	 * <strong>Should</strong> use equals method for comparison instead of compareTo given SortedSet
	 * collection
	 *
	 * @param objects collection to loop over
	 * @param obj Object to look for in the <code>objects</code>
	 * @return true/false whether the given object is found
	 */
	public static boolean collectionContains(Collection<?> objects, Object obj) {
		if (obj == null || objects == null) {
			return false;
		}

		for (Object o : objects) {
			if (o != null && o.equals(obj)) {
				return true;
			}
		}

		return false;
	}

